-- Seed de teste dos cosméticos (scripts/cosmeticos-migration.sql). Nunca rodar em produção.
-- Contas do seed com coleção e itens equipados; Sentinela (Owner) equipa itens que NÃO possui (Owner equipa
-- qualquer um) e precisa parecer um jogador comum no chat e no ranking. Mordomo é Anfitrião (público).

-- O item de exemplo da Fundação não tem arte: fica fora da coleção.
UPDATE item_defs SET active = false WHERE key = 'cosmetico:moldura-exemplo';

-- Fotos de exemplo (recortes da arte do prólogo) para as capturas mostrarem as molduras com rosto.
UPDATE players SET avatar = 'data:image/jpeg;base64,', avatar_updated_at = now() WHERE id = '00000000-0000-4000-8000-000000000002' AND avatar IS NULL;
UPDATE players SET avatar = 'data:image/jpeg;base64,', avatar_updated_at = now() WHERE id = '00000000-0000-4000-8000-000000000003' AND avatar IS NULL;
UPDATE players SET avatar = 'data:image/jpeg;base64,', avatar_updated_at = now() WHERE id = '00000000-0000-4000-8000-000000000010' AND avatar IS NULL;
UPDATE players SET avatar = 'data:image/jpeg;base64,', avatar_updated_at = now() WHERE id = '00000000-0000-4000-8000-000000000011' AND avatar IS NULL;

-- Coleções (idem por jogador e item: rodar de novo não duplica).
SELECT devo_item_grant(p.id::uuid, 'cosmetico:' || x.k, 1, x.motivo, NULL, NULL, 'seed:cos:' || p.n || ':' || x.k)
FROM (VALUES
  ('00000000-0000-4000-8000-000000000003', 'matheus'), ('00000000-0000-4000-8000-000000000002', 'isis'),
  ('00000000-0000-4000-8000-000000000001', 'corvo'), ('00000000-0000-4000-8000-000000000005', 'lirio'),
  ('00000000-0000-4000-8000-000000000004', 'nyx'), ('00000000-0000-4000-8000-000000000011', 'mordomo')) AS p(id, n)
JOIN (VALUES
  ('matheus', 'moldura-heranca-marfim', 'poco'), ('matheus', 'mini-heranca-marfim', 'poco'), ('matheus', 'emblema-rosa-sangue', 'poco'),
  ('matheus', 'balao-correspondencia-real', 'recompensa'), ('matheus', 'mini-fortuna-rato', 'poco'), ('matheus', 'emblema-as-espadas', 'poco'),
  ('matheus', 'emblema-ampulheta-dourada', 'poco'), ('matheus', 'moldura-asas-coruja', 'poco'),
  ('isis', 'moldura-pacto-carmesim', 'poco'), ('isis', 'mini-pacto-carmesim', 'poco'), ('isis', 'emblema-lua-escarlate', 'poco'),
  ('isis', 'balao-confissao-carmesim', 'poco'), ('isis', 'efeito-brasa-carmesim', 'deadly_vote'),
  ('corvo', 'mini-asas-coruja', 'poco'), ('corvo', 'emblema-pena-coruja', 'poco'), ('corvo', 'balao-ultimo-suspiro', 'poco'),
  ('lirio', 'mini-olho-arcano', 'poco'), ('lirio', 'emblema-olho-destino', 'poco'), ('lirio', 'balao-ecos-arcano', 'poco'), ('lirio', 'efeito-geada-prata', 'recompensa'),
  ('nyx', 'mini-fortuna-rato', 'poco'), ('nyx', 'emblema-ficha-javali', 'recompensa'), ('nyx', 'balao-mesa-destino', 'recompensa'),
  ('mordomo', 'moldura-banquete-javali', 'recompensa'), ('mordomo', 'mini-banquete-javali', 'recompensa'), ('mordomo', 'balao-mesa-destino', 'recompensa')
) AS x(n, k, motivo) ON x.n = p.n;

